<?php require __DIR__.'/bootstrap.php';$sent=false;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($message)<5)$error='Please complete the form with a valid email and message.';else{$key=(string)cfg('web3forms_access_key','');if($key){$ch=curl_init('https://api.web3forms.com/submit');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['access_key'=>$key,'subject'=>'Bakery Bake website enquiry','from_name'=>$name,'email'=>$email,'message'=>$message,'replyto'=>$email]),CURLOPT_TIMEOUT=>20]);$r=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode((string)$r,true);$sent=$code>=200&&$code<300&&!empty($d['success']);}if(!$sent){$sent=mail((string)cfg('business_email'),'Bakery Bake website enquiry',"$name <$email>\n\n$message","From: ".cfg('business_email'));}if($sent)add_notification('New website enquiry','Contact form submitted by '.$name,'contact');else$error='We could not send your message right now. Please email or call the bakery directly.';}}site_header('Contact us'); ?>
